for(const sc of screens){if(!sc.tone)continue;const exact=settingsFeedback[sc.id];if(exact){[sc.feedbackTitle,sc.feedbackDetail]=exact;continue;}
 const access=sc.id.match(/^settings-(confirm|pending|rejected)-(read|proposals)-(on|off)$/);
 if(access){const [,stage,kind,on]=access,scope=kind==='read'?'reading':'proposed-change',change=on==='on'?'allow':'stop';
 sc.feedbackTitle=stage==='confirm'?'You are about to '+change+' client '+scope+' access':stage==='pending'?'The '+scope+' rule change isn’t confirmed yet':'Your saved '+scope+' rule is unchanged';
 sc.feedbackDetail=stage==='confirm'?'Confirm the member-level rule only after checking the affected clients. Their individual Persona grants and safeguards still apply.':stage==='pending'?'The previous saved rule stays in use while the change is being confirmed.':'The proposed change was not applied. Review the current rule and its safeguards before retrying.';continue;}
 const client=sc.id.match(/^settings-client-(suspend|resume|revoke)-(pending|done)$/);
 if(client){const [,change,stage]=client,name=change==='resume'?'Planning assistant':'Research assistant',result={suspend:'is now suspended',resume:'is active with its existing read scope',revoke:'has lost future access'}[change];sc.feedbackTitle=stage==='done'?name+' '+result:name+'’s '+{suspend:'suspension',resume:'resume request',revoke:'revocation'}[change]+' isn’t confirmed yet';sc.feedbackDetail=stage==='done'?'The reviewed client change is confirmed. Other clients and their grants have not changed.':'The previously saved client state remains in use. Check the request status before assuming access has changed.';continue;}
 if(sc.id==='settings-planning-revoke-pending'){sc.feedbackTitle='Planning assistant’s revocation isn’t confirmed yet';sc.feedbackDetail='The client stays suspended while the change is pending. Check the saved client state before assuming its grants have been removed.';continue;}
 if(sc.id==='settings-grant-pending'||sc.id==='settings-new-client-grant-pending'){sc.feedbackTitle=sc.id==='settings-grant-pending'?'The Persona grant update isn’t confirmed yet':'The new client’s read grant isn’t confirmed yet';sc.feedbackDetail='Only the previously saved grants are effective. Check the saved scope before assuming a new Persona can be read.';continue;}
 if(sc.id==='settings-profile-pending'){sc.feedbackTitle='Your profile changes aren’t saved to the account yet';sc.feedbackDetail='Wait for confirmation. The previous saved profile stays in use until this update succeeds.';continue;}
 sc.feedbackTitle=sc.title;sc.feedbackDetail=sc.intro;
}
const ids=new Set(screens.map(s=>s.id));if(ids.size!==screens.length)throw Error('Duplicate settings id');for(const s of screens)for(const a of [...s.groups.flatMap(g=>g.rows),...s.actions]){const to=a.to;if(to&&!to.startsWith('@')&&!to.startsWith('!')&&!ids.has(to))throw Error(s.id+' missing '+to);}
module.exports={screens,categories};
